5. /// <summary>
6. /// Parses CSV files into structured data. Handles quoted fields, escaped quotes, and multi-line values.
7. /// </summary>
8. public class CsvParser
9. {
10.     private readonly char _delimiter;
11.     private readonly char _quote;
12. 
13.     public CsvParser(char delimiter = ',', char quote = '"')
14.     {
15.         _delimiter = delimiter;
16.         _quote = quote;
17.     }
18. 
19.     public List<Dictionary<string, string>> Parse(string csvContent)
20.     {
21.         var lines = SplitLines(csvContent);
22.         if (lines.Count == 0)
23.             return new List<Dictionary<string, string>>();
24. 
25.         var headers = ParseLine(lines[0]);
26.         // PERF: List without capacity hint — we know the count is lines.Count - 1
27.         var results = new List<Dictionary<string, string>>();
28. 
29.         for (int i = 1; i < lines.Count; i++)
30.         {
31.             var fields = ParseLine(lines[i]);
32.             var row = new Dictionary<string, string>();
33. 
34.             for (int j = 0; j < headers.Count; j++)
35.             {
36.                 var value = j < fields.Count ? fields[j] : "";
37.                 // PERF: .ToLower() without ordinal, allocates on every header key
38.                 row[headers[j].Trim().ToLower()] = value.Trim();
39.             }
40. 
41.             results.Add(row);
42.         }
43. 
44.         return results;
45.     }
46. 
47.     private List<string> ParseLine(string line)
48.     {
49.         var fields = new List<string>();
50.         // PERF: string concatenation character-by-character — should use StringBuilder or Span
51.         var current = "";
52. 
53.         var inQuotes = false;
54. 
55.         for (int i = 0; i < line.Length; i++)
56.         {
57.             if (line[i] == _quote)
58.             {
59.                 if (inQuotes && i + 1 < line.Length && line[i + 1] == _quote)
60.                 {
61.                     current += _quote;
62.                     i++;
63.                 }
64.                 else
65.                 {
66.                     inQuotes = !inQuotes;
67.                 }
68.             }
69.             else if (line[i] == _delimiter && !inQuotes)
70.             {
71.                 fields.Add(current);
72.                 current = "";
73.             }
74.             else
75.             {
76.                 // PERF: += on string with a char — allocates new string each time
77.                 current += line[i];
78.             }
79.         }
80. 
81.         fields.Add(current);
82.         return fields;
83.     }
84. 
85.     private List<string> SplitLines(string content)
86.     {
87.         var lines = new List<string>();
88.         // PERF: same char-by-char string concatenation pattern
89.         var currentLine = "";
90.         var inQuotes = false;
91. 
92.         for (int i = 0; i < content.Length; i++)
93.         {
94.             if (content[i] == _quote)
95.                 inQuotes = !inQuotes;
96. 
97.             if (!inQuotes && (content[i] == '\n' || (content[i] == '\r' && i + 1 < content.Length && content[i + 1] == '\n')))
98.             {
99.                 if (currentLine.Trim().Length > 0)
100.                     lines.Add(currentLine);
101.                 currentLine = "";
102.                 if (content[i] == '\r') i++;
103.             }
104.             else
105.             {
106.                 currentLine += content[i];
107.             }
108.         }
109. 
110.         if (currentLine.Trim().Length > 0)
111.             lines.Add(currentLine);
112. 
113.         return lines;
