1. namespace Perf01.Services;
2. 
3. /// <summary>
4. /// Configurable data transformation pipeline that processes records through
5. /// a series of stages: validation, transformation, enrichment, and output.
6. /// </summary>
7. public class DataPipeline
8. {
9.     // PERF: unsealed class — JIT cannot devirtualize calls to Record
10.     public class Record
11.     {
12.         public string Id { get; set; } = "";
13.         public Dictionary<string, string> Fields { get; set; } = new();
14.         public List<string> Tags { get; set; } = new();
15.         public DateTime ProcessedAt { get; set; }
16.     }
17. 
18.     public class PipelineResult
19.     {
20.         public List<Record> Processed { get; set; } = new();
21.         public List<(Record Record, string Error)> Failed { get; set; } = new();
22.         public TimeSpan Duration { get; set; }
23.         public Dictionary<string, int> StageMetrics { get; set; } = new();
24.     }
25. 
26.     private readonly List<Func<Record, Record?>> _validators = new();
27.     private readonly List<Func<Record, Record>> _transformers = new();
28.     private readonly List<Func<Record, Record>> _enrichers = new();
29. 
30.     public DataPipeline AddValidator(Func<Record, Record?> validator)
31.     {
32.         _validators.Add(validator);
33.         return this;
34.     }
35. 
36.     public DataPipeline AddTransformer(Func<Record, Record> transformer)
37.     {
38.         _transformers.Add(transformer);
39.         return this;
40.     }
41. 
42.     public DataPipeline AddEnricher(Func<Record, Record> enricher)
43.     {
44.         _enrichers.Add(enricher);
45.         return this;
46.     }
47. 
48.     public PipelineResult Execute(IEnumerable<Record> records)
49.     {
50.         var startTime = DateTime.UtcNow;
51.         var result = new PipelineResult();
52. 
53.         foreach (var record in records)
54.         {
55.             try
56.             {
57.                 var current = record;
58. 
59.                 var valid = true;
60.                 foreach (var validator in _validators)
61.                 {
62.                     var validated = validator(current);
63.                     if (validated == null)
64.                     {
65.                         valid = false;
66.                         result.Failed.Add((record, "Validation failed"));
67.                         break;
68.                     }
69.                     current = validated;
70.                 }
71. 
72.                 if (!valid) continue;
73. 
74.                 foreach (var transformer in _transformers)
75.                 {
76.                     current = transformer(current);
77.                 }
78. 
79.                 foreach (var enricher in _enrichers)
80.                 {
81.                     current = enricher(current);
82.                 }
83. 
84.                 current.ProcessedAt = DateTime.UtcNow;
85.                 result.Processed.Add(current);
86.             }
87.             catch (Exception ex)
88.             {
89.                 // PERF: exception-driven flow — catching generic Exception for expected failures
90.                 result.Failed.Add((record, ex.Message));
91.             }
92.         }
93. 
94.         result.Duration = DateTime.UtcNow - startTime;
95. 
96.         result.StageMetrics["validators"] = _validators.Count;
97.         result.StageMetrics["transformers"] = _transformers.Count;
98.         result.StageMetrics["enrichers"] = _enrichers.Count;
99.         result.StageMetrics["processed"] = result.Processed.Count;
100.         result.StageMetrics["failed"] = result.Failed.Count;
101. 
102.         return result;
103.     }
104. 
105.     public string FormatReport(PipelineResult result)
106.     {
107.         // PERF: string concatenation for building report
108.         var report = "";
109.         report += "Pipeline Execution Report" + "\n";
110.         report += "========================" + "\n";
111.         report += "Duration: " + result.Duration.TotalMilliseconds.ToString("F0") + "ms" + "\n";
112.         report += "Processed: " + result.Processed.Count + "\n";
113.         report += "Failed: " + result.Failed.Count + "\n";
114. 
115.         if (result.Failed.Count > 0)
116.         {
117.             report += "\nFailures:\n";
118.             foreach (var failure in result.Failed)
119.             {
120.                 report += "  " + failure.Record.Id + ": " + failure.Error + "\n";
121.             }
122.         }
123. 
124.         // PERF: nested loop with dictionary lookups — ContainsKey + indexer instead of TryGetValue
125.         var tagCounts = new Dictionary<string, int>();
126.         foreach (var record in result.Processed)
127.         {
128.             foreach (var tag in record.Tags)
129.             {
130.                 if (!tagCounts.ContainsKey(tag))
131.                     tagCounts[tag] = 0;
132.                 tagCounts[tag]++;
133.             }
134.         }
135. 
136.         if (tagCounts.Count > 0)
137.         {
138.             report += "\nTag Distribution:\n";
139.             foreach (var tag in tagCounts.OrderByDescending(t => t.Value))
140.             {
141.                 report += "  " + tag.Key + ": " + tag.Value + "\n";
142.             }
143.         }
144. 
145.         return report;
146.     }
147. 
148.     public static DataPipeline CreateStandardPipeline()
149.     {
150.         return new DataPipeline()
151.             .AddValidator(r =>
152.             {
153.                 if (string.IsNullOrEmpty(r.Id)) return null;
154.                 if (r.Fields.Count == 0) return null;
155.                 return r;
156.             })
157.             .AddTransformer(r =>
158.             {
159.                 // PERF: new Dictionary per record + .ToLower() per field key
160.                 var normalized = new Dictionary<string, string>();
161.                 foreach (var field in r.Fields)
162.                 {
163.                     normalized[field.Key.ToLower()] = field.Value.Trim();
164.                 }
165.                 r.Fields = normalized;
166.                 return r;
167.             })
168.             .AddTransformer(r =>
169.             {
170.                 var cleaned = new Dictionary<string, string>();
171.                 foreach (var field in r.Fields)
172.                 {
173.                     if (!string.IsNullOrWhiteSpace(field.Value))
174.                         cleaned[field.Key] = field.Value;
175.                 }
176.                 r.Fields = cleaned;
177.                 return r;
178.             })
