9.     // PERF: static Dictionary — on .NET 8+ could be FrozenDictionary since it never changes
10.     private static readonly Dictionary<string, Func<object, object>> Converters = new()
11.     {
12.         ["string->int"] = v => int.Parse(v.ToString()!),
13.         ["string->double"] = v => double.Parse(v.ToString()!),
14.         ["string->bool"] = v => bool.Parse(v.ToString()!),
15.         ["string->datetime"] = v => DateTime.Parse(v.ToString()!),
16.         ["int->string"] = v => v.ToString()!,
17.         ["double->string"] = v => v.ToString()!,
18.         ["bool->string"] = v => v.ToString()!.ToLower(),
19.         ["datetime->string"] = v => ((DateTime)v).ToString("o"),
20.     };
21. 
22.     // PERF: unsealed class
23.     public class MappingConfig
24.     {
25.         public Dictionary<string, string> FieldMappings { get; set; } = new();
26.         public Dictionary<string, Func<object, object>> CustomConverters { get; set; } = new();
27.         public HashSet<string> IgnoredFields { get; set; } = new();
28.         public bool StrictMode { get; set; } = false;
29.     }
30. 
31.     public Dictionary<string, object?> Map(
32.         Dictionary<string, object?> source,
33.         MappingConfig config)
34.     {
35.         var result = new Dictionary<string, object?>();
36. 
37.         foreach (var field in source)
38.         {
39.             if (config.IgnoredFields.Contains(field.Key))
40.                 continue;
41. 
42.             // PERF: ContainsKey + indexer instead of TryGetValue
43.             var targetKey = config.FieldMappings.ContainsKey(field.Key)
44.                 ? config.FieldMappings[field.Key]
45.                 : field.Key;
46. 
47.             var value = field.Value;
48. 
49.             if (config.CustomConverters.ContainsKey(field.Key))
50.             {
51.                 value = config.CustomConverters[field.Key](value!);
52.             }
53. 
54.             result[targetKey] = value;
55.         }
56. 
57.         return result;
58.     }
59. 
60.     public List<Dictionary<string, object?>> MapBatch(
61.         IEnumerable<Dictionary<string, object?>> sources,
62.         MappingConfig config)
63.     {
64.         // PERF: no capacity hint on List
65.         var results = new List<Dictionary<string, object?>>();
66.         foreach (var source in sources)
67.         {
68.             results.Add(Map(source, config));
69.         }
70.         return results;
71.     }
72. 
73.     public TTarget MapTo<TTarget>(Dictionary<string, object?> source) where TTarget : new()
74.     {
75.         var target = new TTarget();
76.         // PERF: GetProperties() via reflection on every call — should be cached per type
77.         var properties = typeof(TTarget).GetProperties();
78. 
79.         foreach (var prop in properties)
