     {
         _transformers.Add(transformer);
         return this;
     }

     public DataPipeline AddEnricher(Func<Record, Record> enricher)
     {
         _enrichers.Add(enricher);
         return this;
     }

     public PipelineResult Execute(IEnumerable<Record> records)
     {
