23.     public class MappingConfig
24.     {
25.         public Dictionary<string, string> FieldMappings { get; set; } = new();
26.         public Dictionary<string, Func<object, object>> CustomConverters { get; set; } = new();
27.         public HashSet<string> IgnoredFields { get; set; } = new();
