60.     public List<Dictionary<string, object?>> MapBatch(
61.         IEnumerable<Dictionary<string, object?>> sources,
62.         MappingConfig config)
63.     {
64.         // PERF: no capacity hint on List
65.         var results = new List<Dictionary<string, object?>>();
